CREATE TABLE `token_plans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `token_id` bigint unsigned NOT NULL,
  `plan_id` bigint unsigned NOT NULL,
  `status` tinyint NOT NULL DEFAULT '0',
